package org.ghost.crypto.bridge

/**
 * The pair and provisional key families of Phase 9 design §6.3 and §6.7, as the typed facade
 * exposes them (§2.6 function 15 and the two functions S7 adds, 21 and 22).
 *
 * **Pair keys.** A root is random and generated by the **recipient** of the direction it keys
 * ([offer]); the sender receives it inside an acknowledged session's normal message (§21.3 point
 * 1) and ratchets it forward one week at a time ([keys]). Each week yields an **opening**
 * envelope, which only the native side ever opens, and a **recognition** key, which Kotlin holds
 * in clear and matches hints with — and both are erased together, because recognition is
 * attribution (rule R-S6, mutant PM-36).
 *
 * **Provisional keys.** [provisional] derives the two keys of one session from its `reply_seed`
 * and its Olm session keys. Which of the two this device seals with is not a caller's choice: the
 * role is read off the session's own keys, so a wrong argument cannot produce a key the peer
 * does not recognise.
 */
object DmPairing {

    /** One week's pair key (§6.3). */
    class WeekKey(
        /** The ISO week this key seals and opens. */
        val week: Long,
        /** `dm_pair_key.open_env`: the wrapped week key. */
        val openEnv: ByteArray,
        /** `dm_pair_key.recog_key`: the recognition key, held in clear (rule R-S6). */
        val recognitionKey: ByteArray,
    ) {
        override fun toString(): String = "WeekKey(week=$week)"
    }

    /** The outcome of [keys]. */
    sealed interface KeysResult {
        /** The requested window, one entry per week, ascending. */
        data class Ok(val weeks: List<WeekKey>) : KeysResult

        /** The window is not a window, or is wider than the longest live one (§6.3). */
        data object NonCanonical : KeysResult

        /** The root envelope does not open under its binding (§22.8.3). */
        data object StateCorrupt : KeysResult

        /** The native library is missing or the context is closed. */
        data object Unavailable : KeysResult
    }

    /** A freshly generated root offer (§6.3). */
    class Offer(
        /** `dm_pair_offer.root_env`: the wrapped root. */
        val rootEnv: ByteArray,
        /** `dm_pair_offer.offer_env`: the wrapped 42-byte `seal_root` TLV value (§9.4). */
        val offerEnv: ByteArray,
    ) {
        override fun toString(): String = "Offer(redacted)"
    }

    /** The outcome of [offer]. */
    sealed interface OfferResult {
        /** The root and the TLV bytes that carry it, both wrapped. */
        data class Ok(val offer: Offer) : OfferResult

        /** A malformed argument. */
        data object NonCanonical : OfferResult

        /** The state key could not wrap the root (§22.8.3). */
        data object StateCorrupt : OfferResult

        /** The native library is missing or the context is closed. */
        data object Unavailable : OfferResult
    }

    /** The two provisional keys of one session (§6.7). */
    class Provisional(
        /** The wrapped key this device seals provisional envelopes with. */
        val outEnv: ByteArray,
        /** The direction byte [outEnv] is bound to. */
        val outDirection: Int,
        /** The wrapped key this device opens the peer's provisional envelopes with. */
        val inEnv: ByteArray,
        /** The direction byte [inEnv] is bound to. */
        val inDirection: Int,
        /** The recognition key of [outEnv]. */
        val recognitionOut: ByteArray,
        /** The recognition key of [inEnv]: what an inbound provisional envelope hints. */
        val recognitionIn: ByteArray,
    ) {
        override fun toString(): String = "Provisional(redacted)"
    }

    /** The outcome of [provisional]. */
    sealed interface ProvisionalResult {
        /** Both keys, with the directions the session's own role fixes. */
        data class Ok(val keys: Provisional) : ProvisionalResult

        /** A malformed argument. */
        data object NonCanonical : ProvisionalResult

        /**
         * A stored envelope does not open under its binding, or the session's keys name neither
         * this device nor the contact: not this contact's session (§22.8.3).
         */
        data object StateCorrupt : ProvisionalResult

        /** The native library is missing or the context is closed. */
        data object Unavailable : ProvisionalResult
    }

    /** Where a [keys] walk starts (§6.3). */
    enum class From(val wire: Int) {
        /** From a **root** (`dm_pair_offer.root_env`): the base week's key is derived from it. */
        ROOT(0),

        /**
         * From the **week key** of the base week itself (`dm_pair_key.open_env`).
         *
         * This is what lets a side ratchet forward without keeping the root, which §6.3 requires
         * of both: the sender erases the root as soon as `K_b` exists, and the recipient erases
         * its offer once a pair envelope under that generation opens. `K_{w+1} = HKDF(K_w,
         * "pair-next")` needs only the previous week's key.
         */
        WEEK_KEY(1),
    }

    /**
     * §2.6 function 15: the week keys of `[fromWeek, toWeek]`, ratcheted from [baseWeek].
     *
     * [direction] is the `dm_pair_key.direction` the keys are stored under, which the wrap
     * binding names: `in` for the roots this device offered, `out` for the root the contact sent.
     */
    @Suppress("LongParameterList")
    fun keys(
        handle: Long,
        contactId: ByteArray,
        direction: DmSeal.PairDirection,
        rootGen: Int,
        from: From,
        keyEnv: ByteArray,
        baseWeek: Long,
        fromWeek: Long,
        toWeek: Long,
    ): KeysResult {
        if (!DmNative.isAvailable()) return KeysResult.Unavailable
        val result = dmCall {
            DmNative.pairKeys(
                handle,
                contactId,
                direction.wire,
                rootGen,
                from.wire,
                keyEnv,
                baseWeek,
                fromWeek,
                toWeek,
            )
        }
        return when (result.code) {
            DmCode.OK -> KeysResult.Ok(unpack(result.bytes(DmField.PAIR_KEYS)))
            DmCode.NON_CANONICAL -> KeysResult.NonCanonical
            DmCode.STATE_CORRUPT -> KeysResult.StateCorrupt
            DmCode.CRYPTO_UNAVAILABLE -> KeysResult.Unavailable
            else -> unexpected(result.code, "pairKeys")
        }
    }

    /** Function 22 (S7): the random root this device offers the contact for `c → me` (§6.3). */
    fun offer(handle: Long, contactId: ByteArray, rootGen: Int, baseWeek: Long): OfferResult {
        if (!DmNative.isAvailable()) return OfferResult.Unavailable
        val result = dmCall { DmNative.pairOffer(handle, contactId, rootGen, baseWeek) }
        return when (result.code) {
            DmCode.OK -> OfferResult.Ok(
                Offer(
                    rootEnv = result.bytes(DmField.PAIR_ROOT_ENV),
                    offerEnv = result.bytes(DmField.PAIR_OFFER_ENV),
                ),
            )
            DmCode.NON_CANONICAL -> OfferResult.NonCanonical
            DmCode.STATE_CORRUPT -> OfferResult.StateCorrupt
            DmCode.CRYPTO_UNAVAILABLE -> OfferResult.Unavailable
            else -> unexpected(result.code, "pairOffer")
        }
    }

    /** The outcome of [pqOffer] (slice S13). */
    sealed interface PqOfferResult {
        /**
         * The root and the 1 166-byte `seal_root_pq` value, both wrapped exactly as a classical
         * [Offer]'s are: the offer row, its in-keys and its re-attachment are the classical ones.
         */
        data class Ok(val offer: Offer) : PqOfferResult

        /** A malformed argument. */
        data object NonCanonical : PqOfferResult

        /**
         * The peer's X-Wing key is not valid whole, or encapsulation failed (§22.8.2 rules 3 and
         * 4): the caller falls back to the classical `seal_root` and deletes the `dm_peer_pq` row.
         */
        data object InvalidKey : PqOfferResult

        /** The state key could not wrap the root (§22.8.3). */
        data object StateCorrupt : PqOfferResult

        /** The native library is missing or the context is closed. */
        data object Unavailable : PqOfferResult
    }

    /** The outcome of [pqOpen] (slice S13). */
    sealed interface PqOpenResult {
        /** The root, wrapped under `dm_pair_offer.root_env`'s binding, for [keys] (§6.3). */
        data class Ok(val rootGen: Int, val baseWeek: Long, val rootEnv: ByteArray) : PqOpenResult {
            override fun toString(): String = "Ok(gen=$rootGen, baseWeek=$baseWeek)"
        }

        /** A malformed argument, or a TLV whose `root_gen` is not the one named. */
        data object NonCanonical : PqOpenResult

        /**
         * The TLV names another generation, or its ciphertext does not decapsulate: ignored and
         * counted (§22.8.6 rule 3), and the rest of the L0 applies.
         */
        data object NotOpen : PqOpenResult

        /** The generation's secrets do not open under their binding (§22.8.3). */
        data object StateCorrupt : PqOpenResult

        /** The native library is missing or the context is closed. */
        data object Unavailable : PqOpenResult
    }

    /**
     * §2.6 function 16, sealing half (slice S13): the PQ-C root this device offers the contact for
     * `c → me` (§9.4), encapsulated to the contact's generation [peerGenId] and bound to both Olm
     * identities, that generation and its key. [peerGenId] is a `u32` carried as a `Long`.
     */
    @Suppress("LongParameterList")
    fun pqOffer(
        handle: Long,
        contactId: ByteArray,
        rootGen: Int,
        baseWeek: Long,
        peerOlmIdentity: ByteArray,
        peerGenId: Long,
        peerXwingPublic: ByteArray,
    ): PqOfferResult {
        if (!DmNative.isAvailable()) return PqOfferResult.Unavailable
        val result = dmCall {
            DmNative.pqRootSeal(
                handle,
                contactId,
                rootGen,
                baseWeek,
                peerOlmIdentity,
                peerGenId.toInt(),
                peerXwingPublic,
            )
        }
        return when (result.code) {
            DmCode.OK -> PqOfferResult.Ok(
                Offer(
                    rootEnv = result.bytes(DmField.PAIR_ROOT_ENV),
                    offerEnv = result.bytes(DmField.PAIR_OFFER_ENV),
                ),
            )
            DmCode.NON_CANONICAL -> PqOfferResult.NonCanonical
            DmCode.INVALID_KEY -> PqOfferResult.InvalidKey
            DmCode.STATE_CORRUPT -> PqOfferResult.StateCorrupt
            DmCode.CRYPTO_UNAVAILABLE -> PqOfferResult.Unavailable
            else -> unexpected(result.code, "pqRootSeal")
        }
    }

    /**
     * §2.6 function 16, opening half (slice S13): a received `seal_root_pq` ([DmContent.SealRootPq])
     * opened with this device's generation [genId], which the caller loaded for the TLV's
     * `peer_gen_id`. The contact is the offerer here.
     */
    @Suppress("LongParameterList")
    fun pqOpen(
        handle: Long,
        contactId: ByteArray,
        rootGen: Int,
        genId: Long,
        genSecretsEnv: ByteArray,
        genFallbackPublic: ByteArray,
        tlv: ByteArray,
        peerOlmIdentity: ByteArray,
    ): PqOpenResult {
        if (!DmNative.isAvailable()) return PqOpenResult.Unavailable
        val result = dmCall {
            DmNative.pqRootOpen(
                handle,
                contactId,
                rootGen,
                genId.toInt(),
                genSecretsEnv,
                genFallbackPublic,
                tlv,
                peerOlmIdentity,
            )
        }
        return when (result.code) {
            DmCode.OK -> PqOpenResult.Ok(
                rootGen = result.u32(DmField.ROOT_GEN).toInt(),
                baseWeek = result.i64(DmField.BASE_WEEK),
                rootEnv = result.bytes(DmField.PAIR_ROOT_ENV),
            )
            DmCode.NON_CANONICAL -> PqOpenResult.NonCanonical
            DmCode.NOT_OPEN -> PqOpenResult.NotOpen
            DmCode.STATE_CORRUPT -> PqOpenResult.StateCorrupt
            DmCode.CRYPTO_UNAVAILABLE -> PqOpenResult.Unavailable
            else -> unexpected(result.code, "pqRootOpen")
        }
    }

    /** Function 21 (S7): the two provisional keys of one session (§6.7). */
    fun provisional(
        handle: Long,
        contactId: ByteArray,
        sessionId: ByteArray,
        stateEnv: ByteArray,
        replySeedEnv: ByteArray,
        peerOlmIdentity: ByteArray,
    ): ProvisionalResult {
        if (!DmNative.isAvailable()) return ProvisionalResult.Unavailable
        val result = dmCall {
            DmNative.provisionalKeys(
                handle,
                contactId,
                sessionId,
                stateEnv,
                replySeedEnv,
                peerOlmIdentity,
            )
        }
        return when (result.code) {
            DmCode.OK -> ProvisionalResult.Ok(
                Provisional(
                    outEnv = result.bytes(DmField.PROVISIONAL_OUT_ENV),
                    outDirection = result.byte(DmField.PROVISIONAL_OUT_DIRECTION),
                    inEnv = result.bytes(DmField.PROVISIONAL_IN_ENV),
                    inDirection = result.byte(DmField.PROVISIONAL_IN_DIRECTION),
                    recognitionOut = result.bytes(DmField.RECOGNITION_PROV_OUT),
                    recognitionIn = result.bytes(DmField.RECOGNITION_PROV_IN),
                ),
            )
            DmCode.NON_CANONICAL -> ProvisionalResult.NonCanonical
            DmCode.STATE_CORRUPT -> ProvisionalResult.StateCorrupt
            DmCode.CRYPTO_UNAVAILABLE -> ProvisionalResult.Unavailable
            else -> unexpected(result.code, "provisionalKeys")
        }
    }

    /**
     * `u32_be(count) || (u64_be(week) || u32_be(len) || open_env || recog_key(32))*`.
     *
     * A reply the facade cannot parse is a surface disagreement, which is what
     * `IllegalStateException` is for here: the only producer of these bytes is GHOST's own
     * native code.
     */
    private fun unpack(packed: ByteArray): List<WeekKey> {
        var at = 0
        fun need(count: Int) {
            if (at + count > packed.size) {
                throw IllegalStateException("DM pairKeys reply is truncated")
            }
        }
        fun u32(): Long {
            need(4)
            var value = 0L
            for (i in 0 until 4) value = (value shl 8) or (packed[at + i].toLong() and 0xff)
            at += 4
            return value
        }
        fun u64(): Long {
            need(8)
            var value = 0L
            for (i in 0 until 8) value = (value shl 8) or (packed[at + i].toLong() and 0xff)
            at += 8
            return value
        }
        val count = u32().toInt()
        if (count < 0 || count > MAX_WEEKS) throw IllegalStateException("DM pairKeys count")
        val out = ArrayList<WeekKey>(count)
        repeat(count) {
            val week = u64()
            val length = u32().toInt()
            if (length < 0 || length > MAX_ENVELOPE) throw IllegalStateException("DM pairKeys len")
            need(length)
            val openEnv = packed.copyOfRange(at, at + length)
            at += length
            need(RECOGNITION_BYTES)
            val recognition = packed.copyOfRange(at, at + RECOGNITION_BYTES)
            at += RECOGNITION_BYTES
            out += WeekKey(week, openEnv, recognition)
        }
        if (at != packed.size) throw IllegalStateException("DM pairKeys reply has trailing bytes")
        return out
    }

    /** A recognition key is a 32-byte HKDF output (§6.2). */
    private const val RECOGNITION_BYTES = 32

    /**
     * The widest `toWeek − baseWeek` [keys] will answer, mirroring the crate's own
     * `PAIR_WEEK_WINDOW_MAX`: FRESH is 45 days and a root is replaced every 13 weeks without PQ-C
     * (§6.3), so 26 weeks is twice the longest live window and an unbounded one would be an
     * unbounded loop inside a JNI call.
     *
     * A caller with a wider gap to close ratchets in windows of this size, carrying the last key
     * of one window as the base of the next — which is what [From.WEEK_KEY] exists for.
     */
    const val MAX_WINDOW_WEEKS: Long = 26

    /** The window `pairKeys` refuses to exceed, mirrored here so a bad count is caught early. */
    private const val MAX_WEEKS = MAX_WINDOW_WEEKS.toInt() + 1

    /** A wrapped 32-byte key is 60 bytes; the bound is generous and only guards the parser. */
    private const val MAX_ENVELOPE = 256
}
